<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessageBox}from'element-plus';import{state,refreshPublic,refreshMine}from'../store';import{api,run,downloadReport}from'../api';import type{Row}from'../types';import{date,label}from'../utils';import Icon from'../components/Icon.vue';import Status from'../components/Status.vue';import EntityEditor from'../components/EntityEditor.vue';import RepairTimeline from'../components/RepairTimeline.vue'
const tab=ref('overview'),busy=ref(false),error=ref(''),query=ref(''),status=ref('全部状态'),editor=ref<{kind:'clubs'|'activities'|'equipment';item:Row|null}|null>(null),review=ref<{resource:string;row:Row;status:string;note:string}|null>(null),ticket=ref<Row|null>(null),progress=reactive({status:'PROCESSING',note:''})
const data=reactive<Record<string,Row[]>>({clubs:[],activities:[],equipment:[],applications:[],registrations:[],loans:[],repairs:[],users:[]}),report=ref<Row>({})
const tabs=[{name:'overview',label:'管理概览'},{name:'clubs',label:'社团管理'},{name:'applications',label:'成员审核'},{name:'activities',label:'活动管理'},{name:'registrations',label:'报名记录'},{name:'equipment',label:'器材登记'},{name:'loans',label:'借还审核'},{name:'repairs',label:'维修工单'},{name:'users',label:'用户权限'},{name:'reports',label:'数据报表'}]
const includeArchived=ref(false)
function visibleRecord(r:Row){if(includeArchived.value)return true;if(tab.value==='clubs'||tab.value==='equipment')return r.active!==false;const currentClubIds=new Set(data.clubs.filter(c=>c.active).map(c=>c.id));if(tab.value==='activities')return currentClubIds.has(r.clubId);if(tab.value==='applications')return r.club?.active!==false;if(tab.value==='registrations')return currentClubIds.has(r.activity?.clubId);if(tab.value==='loans')return r.equipment?.active!==false;if(tab.value==='repairs')return !r.equipmentId||data.equipment.find(e=>e.id===r.equipmentId)?.active!==false;return true}
const filtered=computed(()=>(data[tab.value]||[]).filter(visibleRecord).filter(r=>(status.value==='全部状态'||r.status===status.value)&&(!query.value||JSON.stringify(r).toLowerCase().includes(query.value.toLowerCase()))))
const statuses=computed(()=>[...new Set((data[tab.value]||[]).map(r=>r.status).filter(Boolean))])
const activityMaximum=computed(()=>Math.max(1,...(report.value.trend||[]).map((x:Row)=>x.activities)))
const memberMaximum=computed(()=>Math.max(1,...(report.value.clubs||[]).map((x:Row)=>x.members)))
const progressOptions=computed(()=>ticket.value?.status==='OPEN'?['PROCESSING']:ticket.value?.status==='PROCESSING'?['PROCESSING','RESOLVED']:ticket.value?.status==='RESOLVED'?['PROCESSING','CLOSED']:[])
async function load(){busy.value=true;error.value='';try{const keys=Object.keys(data);const result=await Promise.all(keys.map(k=>api<Row[]>('/admin/'+k)));keys.forEach((k,i)=>data[k]=result[i]!);report.value=await api('/admin/reports')}catch(e){error.value=e instanceof Error?e.message:'无法加载'}finally{busy.value=false}}
function switchTab(name:string){tab.value=name;query.value='';status.value='全部状态'}
async function saved(){editor.value=null;await Promise.all([load(),refreshPublic(),refreshMine()])}
function openReview(resource:string,row:Row,value:string){review.value={resource,row,status:value,note:''}}
async function submitReview(){if(!review.value)return;busy.value=true;await run(async()=>{const r=review.value!;await api(`/admin/${r.resource}/${r.row.id}/review`,'PUT',{status:r.status,note:r.note});review.value=null;await saved()},'审核已完成');busy.value=false}
function openTicket(row:Row){ticket.value=row;progress.status=row.status==='RESOLVED'?'CLOSED':'PROCESSING';progress.note=''}
async function submitProgress(){if(!ticket.value||!progress.note.trim())return;busy.value=true;await run(async()=>{await api(`/admin/repairs/${ticket.value!.id}/progress`,'POST',progress);const id=ticket.value!.id;await saved();ticket.value=data.repairs.find(r=>r.id===id)||null;progress.note='';progress.status=ticket.value?.status==='RESOLVED'?'CLOSED':'PROCESSING'},'工单进度已更新');busy.value=false}
async function changeAccess(row:Row,role:string,enabled:boolean){if(!await ElMessageBox.confirm(`确认将 ${row.name} 的账号${enabled?'启用':'停用'}，角色设为${label(role)}？`,'用户权限变更',{confirmButtonText:'确认变更',cancelButtonText:'取消',type:'warning'}).then(()=>true).catch(()=>false))return;await run(async()=>{await api(`/admin/users/${row.id}/access`,'PUT',{role,enabled});await load()},'权限已更新')}
onMounted(load)
</script>
<template><div class="page-content"><div class="page-heading"><div><div class="eyebrow">征途单车俱乐部 · 管理员后台</div><h1>管理工作台<span class="greeting-dot">.</span></h1><p>管理入社审核、骑行活动、器材借还与维修工单，查看真实业务统计。</p></div><el-button @click="load" :loading="busy"><Icon name="activity" :size="16"/>刷新数据</el-button></div><div class="admin-nav"><button v-for="t in tabs" :key="t.name" :class="{active:tab===t.name}" @click="switchTab(t.name)">{{t.label}}<span v-if="t.name==='applications'&&report.pendingApplications">{{report.pendingApplications}}</span></button></div><div v-if="error" class="info-box">{{error}}<el-button type="primary" link @click="load">重新加载</el-button></div>
<template v-if="tab==='overview'"><div class="stats-grid admin-stats"><div v-for="s in [{label:'注册用户',value:report.userCount,icon:'users'},{label:'社团成员',value:report.memberCount,icon:'compass'},{label:'报名人次',value:report.registrationCount,icon:'calendar'},{label:'在借器材',value:report.equipmentBorrowed,icon:'package'}]" :key="s.label" class="stat-card"><div><span class="stat-label">{{s.label}}</span><b>{{s.value??0}}</b></div><span class="stat-icon green"><Icon :name="s.icon" :size="23"/></span></div></div><div class="admin-overview-grid"><section class="panel admin-chart"><div class="section-heading"><div><h3>骑行活动趋势</h3><p>近 6 个月已发布活动数量</p></div><Icon name="trend" :size="21"/></div><div class="bar-chart"><div v-for="point in report.trend||[]" :key="point.month" class="bar-column"><b>{{point.activities}}</b><div class="bar-track"><span :style="{height:(point.activities/activityMaximum*100)+'%'}" :title="point.month+'：'+point.activities+' 场活动'"/></div><small>{{point.month.slice(5)}} 月</small></div></div></section><section class="panel todo-panel"><div class="section-heading"><h3>待办事项</h3><span class="heading-badge">实时数据</span></div><button @click="switchTab('applications');status='PENDING'"><span class="stat-icon green"><Icon name="users"/></span><span><b>入社申请待审核</b><small>审核征途单车俱乐部的加入申请</small></span><strong>{{report.pendingApplications||0}}</strong><Icon name="right" :size="16"/></button><button @click="switchTab('loans')"><span class="stat-icon orange"><Icon name="package"/></span><span><b>借还申请待处理</b><small>借用审批与归还验收</small></span><strong>{{report.pendingLoans||0}}</strong><Icon name="right" :size="16"/></button><button @click="switchTab('repairs')"><span class="stat-icon purple"><Icon name="wrench"/></span><span><b>待解决维修工单</b><small>受理问题，更新处理进展</small></span><strong>{{report.openRepairs||0}}</strong><Icon name="right" :size="16"/></button></section></div><section class="panel admin-chart"><div class="section-heading"><h3>社团成员分布</h3><span class="muted small">同一学生可以加入多个社团</span></div><div class="club-bars"><div v-for="club in report.clubs||[]" :key="club.name"><span>{{club.name}}</span><div><i :style="{width:club.members/memberMaximum*100+'%'}"/></div><b>{{club.members}} 人</b></div></div></section></template>
<template v-else-if="tab==='reports'"><div class="reports-heading panel"><Icon name="download" :size="35"/><div><h3>让每一次参与，都有迹可循</h3><p>导出实时 CSV 报表，支持 Excel 打开，包含中文列名与完整统计。</p></div></div><div class="report-grid"><article v-for="r in [{type:'members',name:'社团成员报表',desc:'入社申请、学号院系与审核状态',icon:'users'},{type:'activities',name:'活动情况报表',desc:'活动安排、报名人数与签到统计',icon:'calendar'},{type:'equipment',name:'器材使用报表',desc:'资产库存、借用情况与申请次数',icon:'package'},{type:'repairs',name:'维修工单报表',desc:'工单状态、报修地点与处理记录',icon:'wrench'}]" :key="r.type" class="panel report-card"><span class="stat-icon green"><Icon :name="r.icon" :size="27"/></span><h3>{{r.name}}</h3><p>{{r.desc}}</p><el-button type="primary" plain @click="downloadReport(r.type)"><Icon name="download" :size="16"/>导出 CSV</el-button></article></div><div class="stats-grid admin-stats"><div v-for="s in [{label:'已签到人次',value:report.checkinCount},{label:'有效社团成员关系',value:report.membershipCount},{label:'共享器材总数',value:report.equipmentTotal},{label:'活动总数',value:report.activityCount}]" :key="s.label" class="stat-card"><div><span class="stat-label">{{s.label}}</span><b>{{s.value||0}}</b></div></div></div><section class="panel"><h3 class="panel-title">器材使用详情</h3><el-table :data="report.equipment||[]" stripe><el-table-column prop="name" label="器材名称" min-width="200"/><el-table-column prop="total" label="总数量"/><el-table-column prop="borrowed" label="在借数量"/><el-table-column prop="loanCount" label="累计申请次数"/></el-table></section></template>
<section v-else class="panel admin-table-panel" v-loading="busy"><div class="admin-table-toolbar"><h3>{{tabs.find(t=>t.name===tab)?.label}}<span class="muted small">{{filtered.length}} 条记录</span></h3><div><el-checkbox v-if="tab!=='users'" v-model="includeArchived">包含归档记录</el-checkbox><el-input v-model="query" clearable placeholder="搜索当前列表" class="admin-search"><template #prefix><Icon name="search" :size="15"/></template></el-input><el-select v-if="statuses.length" v-model="status" class="status-select"><el-option label="全部状态" value="全部状态"/><el-option v-for="s in statuses" :key="s" :label="label(s)" :value="s"/></el-select><el-button v-if="['clubs','activities','equipment'].includes(tab)" type="primary" @click="editor={kind:tab as any,item:null}"><Icon name="plus" :size="16"/>新增{{tab==='clubs'?'社团':tab==='activities'?'活动':'器材'}}</el-button></div></div>
<el-table :data="filtered" stripe empty-text="暂无匹配记录" row-key="id"><el-table-column label="编号" width="75"><template #default="{row}">#{{row.id}}</template></el-table-column>
<template v-if="tab==='clubs'"><el-table-column prop="name" label="社团名称" min-width="180"/><el-table-column prop="category" label="分类" width="110"/><el-table-column prop="memberCount" label="成员数" width="90"/><el-table-column label="运营状态" min-width="130"><template #default="{row}"><el-tag :type="row.active?'success':'info'" size="small">{{row.active?(row.recruiting?'正在招新':'正常运营'):'已归档'}}</el-tag></template></el-table-column><el-table-column prop="location" label="地点" min-width="170"/></template>
<template v-if="tab==='activities'"><el-table-column label="活动名称" min-width="250"><template #default="{row}"><b>{{row.title}}</b><p class="muted small">{{row.clubName}}</p></template></el-table-column><el-table-column label="开始时间" min-width="160"><template #default="{row}">{{date(row.startsAt,true)}}</template></el-table-column><el-table-column label="报名" width="100"><template #default="{row}">{{row.registrationCount}} / {{row.capacity}}</template></el-table-column><el-table-column prop="checkinCode" label="签到码" min-width="130"/><el-table-column label="状态" width="100"><template #default="{row}"><Status :value="row.status"/></template></el-table-column></template>
<template v-if="tab==='equipment'"><el-table-column prop="name" label="器材名称" min-width="210"/><el-table-column prop="assetCode" label="资产编号" min-width="135"/><el-table-column label="库存" width="120"><template #default="{row}">可用 {{row.availableQuantity}} / {{row.totalQuantity}}</template></el-table-column><el-table-column prop="location" label="位置" min-width="155"/><el-table-column label="状态" width="95"><template #default="{row}"><el-tag :type="row.active?'success':'info'" size="small">{{row.active?'可借用':'已停用'}}</el-tag></template></el-table-column></template>
<template v-if="tab==='applications'"><el-table-column label="申请人" min-width="160"><template #default="{row}"><b>{{row.user.name}}</b><p class="muted small">{{row.user.studentNo}}</p></template></el-table-column><el-table-column label="社团" min-width="170"><template #default="{row}">{{row.club.name}}</template></el-table-column><el-table-column prop="reason" label="加入理由" min-width="240" show-overflow-tooltip/><el-table-column label="状态" width="100"><template #default="{row}"><Status :value="row.status"/></template></el-table-column><el-table-column label="操作" min-width="155"><template #default="{row}"><template v-if="row.status==='PENDING'"><el-button type="primary" link @click="openReview('applications',row,'APPROVED')">通过</el-button><el-button type="danger" link @click="openReview('applications',row,'REJECTED')">驳回</el-button></template><span v-else class="muted small">{{row.reviewNote||'已处理'}}</span></template></el-table-column></template>
<template v-if="tab==='registrations'"><el-table-column label="报名人" min-width="160"><template #default="{row}"><b>{{row.user.name}}</b><p class="muted small">{{row.user.studentNo}}</p></template></el-table-column><el-table-column label="活动" min-width="230"><template #default="{row}">{{row.activity.title}}</template></el-table-column><el-table-column label="报名时间" min-width="155"><template #default="{row}">{{date(row.createdAt,true)}}</template></el-table-column><el-table-column label="签到" min-width="165"><template #default="{row}"><el-tag :type="row.checkedInAt?'success':'info'" size="small">{{row.checkedInAt?'已签到':'未签到'}}</el-tag><p v-if="row.checkedInAt" class="small muted">{{date(row.checkedInAt,true)}}</p></template></el-table-column></template>
<template v-if="tab==='loans'"><el-table-column label="借用人 / 器材" min-width="240"><template #default="{row}"><b>{{row.equipment.name}} × {{row.quantity}}</b><p class="muted small">{{row.user.name}} · {{row.purpose}}</p></template></el-table-column><el-table-column label="归还日期" min-width="130"><template #default="{row}">{{row.dueDate}}<el-tag v-if="row.overdue" type="danger" size="small">逾期</el-tag></template></el-table-column><el-table-column label="状态" min-width="130"><template #default="{row}"><Status :value="row.status"/></template></el-table-column><el-table-column label="操作" min-width="170"><template #default="{row}"><template v-if="row.status==='PENDING'"><el-button type="primary" link @click="openReview('loans',row,'APPROVED')">批准借用</el-button><el-button type="danger" link @click="openReview('loans',row,'REJECTED')">驳回</el-button></template><el-button v-else-if="row.status==='RETURN_PENDING'" type="primary" link @click="openReview('loans',row,'RETURNED')">验收并确认归还</el-button><span v-else class="muted small">{{row.reviewNote||'—'}}</span></template></el-table-column></template>
<template v-if="tab==='repairs'"><el-table-column label="维修工单" min-width="230"><template #default="{row}"><b>{{row.title}}</b><p class="muted small">{{row.user.name}} · {{row.location}}</p></template></el-table-column><el-table-column label="优先级" width="100"><template #default="{row}"><Status :value="row.priority"/></template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><Status :value="row.status"/></template></el-table-column><el-table-column label="提交时间" min-width="160"><template #default="{row}">{{date(row.createdAt,true)}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button type="primary" link @click="openTicket(row)">查看 / 处理</el-button></template></el-table-column></template>
<template v-if="tab==='users'"><el-table-column label="姓名 / 用户名" min-width="170"><template #default="{row}"><b>{{row.name}}</b><p class="muted small">{{row.username}}</p></template></el-table-column><el-table-column prop="studentNo" label="学号" min-width="140"/><el-table-column prop="department" label="院系" min-width="190"/><el-table-column label="角色" width="100"><template #default="{row}"><Status :value="row.role"/></template></el-table-column><el-table-column label="账号" width="85"><template #default="{row}"><el-tag :type="row.enabled?'success':'danger'" size="small">{{row.enabled?'正常':'停用'}}</el-tag></template></el-table-column><el-table-column label="权限操作" min-width="210"><template #default="{row}"><span v-if="row.id===state.user?.id" class="muted">当前账号</span><template v-else><el-button type="primary" link @click="changeAccess(row,row.role==='ADMIN'?'STUDENT':'ADMIN',row.enabled)">{{row.role==='ADMIN'?'设为学生':'设为管理员'}}</el-button><el-button :type="row.enabled?'danger':'success'" link @click="changeAccess(row,row.role,!row.enabled)">{{row.enabled?'停用':'启用'}}</el-button></template></template></el-table-column></template>
<el-table-column v-if="['clubs','activities','equipment'].includes(tab)" label="操作" width="95" fixed="right"><template #default="{row}"><el-button type="primary" link @click="editor={kind:tab as any,item:row}">编辑</el-button></template></el-table-column></el-table><p class="table-help" v-if="tab==='clubs'">社团可在编辑中关闭招新或归档；历史成员与活动记录会保留。</p><p class="table-help" v-if="tab==='activities'">签到码仅对管理员展示，请在活动现场提供给参与者。取消活动后不再允许报名或签到。</p><p class="table-help" v-if="tab==='equipment'">编辑总库存时，系统会保留在借数量；停用后不再接受新借用申请。</p></section></div>
<EntityEditor v-if="editor" :kind="editor.kind" :item="editor.item" :clubs="data.clubs" @close="editor=null" @saved="saved"/>
<el-dialog :model-value="!!review" @update:model-value="(v:boolean)=>{if(!v)review=null}" title="审核申请" width="min(500px, 94vw)"><template v-if="review"><p>{{review.row.user.name}} · {{review.resource==='applications'?review.row.club.name:review.row.equipment.name}}</p><div class="info-box">本次处理：{{label(review.status)}}<p v-if="review.status==='RETURNED'">请确认实物和配件已验收。确认后会恢复可用库存。</p></div><el-input v-model="review.note" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="填写审核意见（可选）"/></template><template #footer><el-button @click="review=null">取消</el-button><el-button type="primary" :loading="busy" @click="submitReview">确认审核</el-button></template></el-dialog>
<el-dialog :model-value="!!ticket" @update:model-value="(v:boolean)=>{if(!v)ticket=null}" title="维修工单处理" width="min(700px, 94vw)"><template v-if="ticket"><RepairTimeline :ticket="ticket"/><el-form v-if="ticket.status!=='CLOSED'" label-position="top" @submit.prevent="submitProgress"><h3>更新处理进度</h3><el-form-item label="处理后状态"><el-select v-model="progress.status"><el-option v-for="s in progressOptions" :key="s" :label="label(s)" :value="s"/></el-select></el-form-item><el-form-item label="处理说明" required><el-input v-model="progress.note" type="textarea" :rows="3" maxlength="1000" show-word-limit placeholder="说明处理措施、当前进展或修复结果"/></el-form-item><el-button type="primary" :loading="busy" :disabled="!progress.note.trim()" @click="submitProgress">提交进度更新</el-button></el-form></template></el-dialog></template>
